const humanized = $input.first().json;
const scoreResult = $('Étape 7 — Score Anti-IA').item.json;
const originalSource = $('Extraction Input').item.json.source;
const targetScore = parseInt($('Extraction Input').item.json.target_score);

let scoreData;
try {
  const content = scoreResult.message?.content || scoreResult.message?.text || JSON.stringify(scoreResult);
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  scoreData = jsonMatch ? JSON.parse(jsonMatch[0]) : { score: 5, flags: ['parse_error'], patterns: [] };
} catch(e) {
  scoreData = { score: 5, flags: ['parse_error'], patterns: [] };
}

const passed = scoreData.score <= targetScore;

return {
  json: {
    text: humanized.message?.content || humanized.message?.text || '',
    anti_ia_score: scoreData.score,
    anti_ia_flags: scoreData.flags,
    anti_ia_patterns: scoreData.patterns,
    passed: passed,
    source: originalSource,
    target_score: targetScore,
    processed_at: new Date().toISOString()
  }
};
